def split_csv(line):
    """
    Parse one line of CSV and return its fields as a list of strings.
    Returns None if the line is malformed.
    """
    fields = []
    i = 0

    while i < len(line):
        if line[i] == '"':
            # Quoted field
            field = ""
            i += 1
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote or end of field
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - add single quote to field
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Must be followed by comma or end of line
                        if i < len(line) and line[i] != ',':
                            return None
                        fields.append(field)
                        if i < len(line):
                            i += 1  # Skip the comma
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without finding closing quote
                return None
        else:
            # Unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field must not contain quotes
                    return None
                field += line[i]
                i += 1
            fields.append(field)
            if i < len(line):
                i += 1  # Skip the comma

    return fields

